package org.searlelab.context.mprophet;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.Test;

/**
 * CTX018-006: the Java port reproduces Context-MS's fdr.py on the reference values in ctx018_fdr_reference.tsv
 * (generated by docs/validation/ctx018_fdr_fixture.py from Context-MS d207f47). Tolerances were set from the
 * observed differences (2026-11-01, largest over all sets: p 7.7e-15 relative, q 7.7e-15 relative, PEP 1.6e-15
 * absolute) with a margin of about 10^4-10^6; they cover summation order and the erfc implementation (commons-math
 * vs scipy), not algorithmic differences.
 */
public class MProphetConfidenceTest {
	private static final Path FIXTURE = Path.of("src/test/resources/org/searlelab/context/mprophet/ctx018_fdr_reference.tsv");
	static final double P_RELATIVE = 1e-10;
	static final double Q_RELATIVE = 1e-9;
	static final double PEP_ABSOLUTE = 1e-9;

	private static final class Set {
		final List<Double> targets = new ArrayList<>(), decoys = new ArrayList<>(), p = new ArrayList<>(),
				q = new ArrayList<>(), pep = new ArrayList<>();
	}

	private static Map<String, Set> fixture() throws IOException {
		Map<String, Set> sets = new LinkedHashMap<>();
		for (String line : Files.readAllLines(FIXTURE)) {
			if (line.startsWith("#") || line.startsWith("set\t")) continue;
			String[] f = line.split("\t", -1);
			Set set = sets.computeIfAbsent(f[0], k -> new Set());
			if (f[1].equals("target")) {
				set.targets.add(Double.parseDouble(f[2]));
				set.p.add(Double.parseDouble(f[3]));
				set.q.add(Double.parseDouble(f[4]));
				set.pep.add(Double.parseDouble(f[5]));
			} else {
				set.decoys.add(Double.parseDouble(f[2]));
			}
		}
		return sets;
	}

	private static double[] array(List<Double> values) {
		return values.stream().mapToDouble(Double::doubleValue).toArray();
	}

	private static void assertRelative(String what, double expected, double actual, double tolerance) {
		double scale = Math.max(Math.abs(expected), Double.MIN_NORMAL);
		assertTrue(what + ": expected " + expected + " but was " + actual, Math.abs(expected - actual) <= tolerance * scale
				|| Math.abs(expected - actual) <= 1e-300);
	}

	@Test
	public void matchesContextMSOnEveryReferenceSet() throws IOException {
		Map<String, Set> sets = fixture();
		assertEquals(5, sets.size());
		for (Map.Entry<String, Set> entry : sets.entrySet()) {
			Set set = entry.getValue();
			double[] targets = array(set.targets), decoys = array(set.decoys);
			double[] p = MProphetConfidence.gaussianPValues(targets, decoys);
			MProphetConfidence.Confidence confidence = MProphetConfidence.qAndPep(targets, decoys);
			for (int i = 0; i < targets.length; i++) {
				String where = entry.getKey() + " target " + i;
				assertRelative(where + " p", set.p.get(i), p[i], P_RELATIVE);
				assertRelative(where + " q", set.q.get(i), confidence.q()[i], Q_RELATIVE);
				assertEquals(where + " PEP", set.pep.get(i), confidence.pep()[i], PEP_ABSOLUTE);
			}
		}
	}

	@Test
	public void benjaminiHochbergMatchesAHandWorkedExample() {
		// p sorted: 0.01, 0.02, 0.03, 0.5 (m = 4) -> p*m/rank = 0.04, 0.04, 0.04, 0.5, then the running minimum
		// from the largest p down.
		assertArrayEquals(new double[] { 0.5, 0.04, 0.04, 0.04 },
				MProphetConfidence.benjaminiHochberg(new double[] { 0.5, 0.03, 0.01, 0.02 }), 1e-15);
		// Tied p: 0.04 and 0.02 before the running minimum, so both become 0.02.
		assertArrayEquals(new double[] { 0.02, 0.02 }, MProphetConfidence.benjaminiHochberg(new double[] { 0.02, 0.02 }), 1e-15);
	}

	@Test
	public void pi0IsTheMedianOverLambdaAndPEPsAreFlooredBy005() {
		// All p near zero: every lambda sees no p above it, so pi0 = 0 and the floor of 0.05 applies.
		double[] p = new double[20];
		for (int i = 0; i < p.length; i++) p[i] = 1e-6 * (i + 1);
		assertEquals(0.0, MProphetConfidence.estimatePi0(p), 0.0);
		// All p above every lambda: the nine estimates are 1/(1 - lambda); their median (lambda = 0.5) is 2.
		assertEquals(2.0, MProphetConfidence.estimatePi0(new double[] { 0.95, 0.95 }), 1e-12);
		double[] pep = MProphetConfidence.localFdr(p);
		for (int i = 1; i < pep.length; i++) assertTrue("PEP must not decrease with p", pep[i] >= pep[i - 1]);
		assertTrue(pep[0] > 0);
	}

	@Test
	public void degenerateInputsAreHandledLikeContextMS() {
		// No decoys: every p is 1, so every q and PEP is 1.
		MProphetConfidence.Confidence none = MProphetConfidence.qAndPep(new double[] { 3, 2 }, new double[0]);
		assertArrayEquals(new double[] { 1, 1 }, none.q(), 0.0);
		assertArrayEquals(new double[] { 1, 1 }, none.pep(), 0.0);
		// Constant decoys (SD 0): p is 0 above the decoy value and 1 at or below it.
		assertArrayEquals(new double[] { 0, 1, 1 },
				MProphetConfidence.gaussianPValues(new double[] { 2, 1, 0 }, new double[] { 1, 1 }), 0.0);
		// Identical logit p (zero KDE spread) and a single target: PEP 1, as Context-MS's fallback gives.
		assertArrayEquals(new double[] { 1, 1 }, MProphetConfidence.localFdr(new double[] { 0.3, 0.3 }), 0.0);
		assertArrayEquals(new double[] { 1 }, MProphetConfidence.localFdr(new double[] { 0.3 }), 0.0);
		// No targets at all.
		assertEquals(0, MProphetConfidence.qAndPep(new double[0], new double[] { 1 }).q().length);
	}
}
